PRAGMA foreign_keys=ON;
CREATE TABLE metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE branches(branch_id INTEGER PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE customers(customer_id INTEGER PRIMARY KEY,name TEXT NOT NULL,terms_days INTEGER NOT NULL CHECK(terms_days>=0));
CREATE TABLE employees(employee_id INTEGER PRIMARY KEY,name TEXT NOT NULL,branch_id INTEGER REFERENCES branches);
CREATE TABLE roles(role_id TEXT PRIMARY KEY);
CREATE TABLE permissions(role_id TEXT REFERENCES roles,action TEXT,PRIMARY KEY(role_id,action));
CREATE TABLE employee_roles(employee_id INTEGER REFERENCES employees,role_id TEXT REFERENCES roles,PRIMARY KEY(employee_id,role_id));
CREATE TABLE products(product_id INTEGER PRIMARY KEY,name TEXT,unit_price_cents INTEGER NOT NULL CHECK(typeof(unit_price_cents)='integer' AND unit_price_cents>0));
CREATE TABLE orders(order_id INTEGER PRIMARY KEY,customer_id INTEGER NOT NULL REFERENCES customers,branch_id INTEGER NOT NULL REFERENCES branches,order_date TEXT NOT NULL,created_by INTEGER REFERENCES employees);
CREATE TABLE order_lines(order_id INTEGER REFERENCES orders,line_no INTEGER,product_id INTEGER REFERENCES products,quantity INTEGER CHECK(quantity>0),unit_price_cents INTEGER CHECK(typeof(unit_price_cents)='integer'),PRIMARY KEY(order_id,line_no));
CREATE TABLE shipments(shipment_id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders,ship_date TEXT NOT NULL,shipped_by INTEGER REFERENCES employees);
CREATE TABLE shipment_lines(shipment_id INTEGER REFERENCES shipments,line_no INTEGER,order_id INTEGER,line_ref INTEGER,quantity INTEGER CHECK(quantity>0),PRIMARY KEY(shipment_id,line_no),FOREIGN KEY(order_id,line_ref) REFERENCES order_lines(order_id,line_no));
CREATE TABLE invoices(invoice_id INTEGER PRIMARY KEY,invoice_no TEXT NOT NULL,order_id INTEGER NOT NULL REFERENCES orders,invoice_date TEXT NOT NULL,due_date TEXT NOT NULL,recognition_date TEXT NOT NULL,amount_cents INTEGER NOT NULL CHECK(typeof(amount_cents)='integer' AND amount_cents>=0),created_by INTEGER REFERENCES employees);
CREATE TABLE invoice_lines(invoice_id INTEGER REFERENCES invoices,line_no INTEGER,order_id INTEGER,line_ref INTEGER,quantity INTEGER CHECK(quantity>0),unit_price_cents INTEGER CHECK(typeof(unit_price_cents)='integer'),PRIMARY KEY(invoice_id,line_no),FOREIGN KEY(order_id,line_ref) REFERENCES order_lines(order_id,line_no));
CREATE TABLE returns(return_id INTEGER PRIMARY KEY,invoice_id INTEGER REFERENCES invoices,return_date TEXT NOT NULL,amount_cents INTEGER CHECK(typeof(amount_cents)='integer' AND amount_cents>0));
CREATE TABLE credit_memos(credit_id INTEGER PRIMARY KEY,invoice_id INTEGER REFERENCES invoices,return_id INTEGER REFERENCES returns,credit_date TEXT NOT NULL,amount_cents INTEGER CHECK(typeof(amount_cents)='integer' AND amount_cents>0));
CREATE TABLE payments(payment_id INTEGER PRIMARY KEY,customer_id INTEGER REFERENCES customers,payment_date TEXT NOT NULL,amount_cents INTEGER CHECK(typeof(amount_cents)='integer' AND amount_cents>0));
CREATE TABLE allocations(allocation_id INTEGER PRIMARY KEY,payment_id INTEGER REFERENCES payments,invoice_id INTEGER REFERENCES invoices,allocation_date TEXT NOT NULL,amount_cents INTEGER CHECK(typeof(amount_cents)='integer' AND amount_cents>0));
CREATE TABLE accounts(account_id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE journal_entries(journal_id INTEGER PRIMARY KEY,entry_date TEXT NOT NULL,posting_date TEXT NOT NULL,source_type TEXT NOT NULL CHECK(source_type IN ('opening','invoice','payment','credit','manual')),invoice_id INTEGER REFERENCES invoices,payment_id INTEGER REFERENCES payments,credit_id INTEGER REFERENCES credit_memos,branch_id INTEGER REFERENCES branches,prepared_by INTEGER REFERENCES employees,manual INTEGER NOT NULL CHECK(manual IN (0,1)));
CREATE TABLE journal_lines(journal_id INTEGER REFERENCES journal_entries,line_no INTEGER,account_id TEXT REFERENCES accounts,debit_cents INTEGER NOT NULL CHECK(typeof(debit_cents)='integer' AND debit_cents>=0),credit_cents INTEGER NOT NULL CHECK(typeof(credit_cents)='integer' AND credit_cents>=0),PRIMARY KEY(journal_id,line_no),CHECK((debit_cents>0 AND credit_cents=0) OR (credit_cents>0 AND debit_cents=0)));
CREATE TABLE approvals(approval_id INTEGER PRIMARY KEY,journal_id INTEGER REFERENCES journal_entries,approved_by INTEGER REFERENCES employees,approval_date TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('approved','rejected')));
CREATE TABLE activity_logs(log_id INTEGER PRIMARY KEY,employee_id INTEGER REFERENCES employees,action TEXT NOT NULL,activity_date TEXT NOT NULL,invoice_id INTEGER REFERENCES invoices,journal_id INTEGER REFERENCES journal_entries);
CREATE INDEX idx_ship_order ON shipments(order_id);
CREATE INDEX idx_invoice_order ON invoices(order_id);
CREATE INDEX idx_alloc_invoice ON allocations(invoice_id,allocation_date);
CREATE INDEX idx_credits_invoice ON credit_memos(invoice_id,credit_date);
CREATE INDEX idx_journal_invoice ON journal_entries(invoice_id);
CREATE INDEX idx_journal_dates ON journal_entries(entry_date,posting_date);
CREATE INDEX idx_alloc_payment ON allocations(payment_id);
CREATE INDEX idx_activity_invoice ON activity_logs(invoice_id,action,employee_id);
